import React, { useEffect, useState, useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Map, { Marker, NavigationControl } from 'react-map-gl/maplibre';
import { Client } from '@stomp/stompjs';
import SockJS from 'sockjs-client';
import { ArrowLeft, Clock, Activity, Play, Pause, Plane, Truck, Compass, Layers, X, Camera, Crosshair, Gauge, Maximize2, Navigation, Search } from 'lucide-react';
import { useTheme } from '../context/ThemeContext';
import { getVehicleColor } from './ManageFleetPage';

export default function VehicleHistoryPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { theme } = useTheme();
  const mapRef = useRef(null);

  const [history, setHistory] = useState([]);
  const [vehicles, setVehicles] = useState([]);
  const [vehicle, setVehicle] = useState(null);
  const [currentIndex, setCurrentIndex] = useState(0);

  const [isLive, setIsLive] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isHudExpanded, setIsHudExpanded] = useState(true);
  const [autoFollow, setAutoFollow] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isBackHovered, setIsBackHovered] = useState(false); // Hover state for back button

  const [viewState, setViewState] = useState({
    longitude: -122.4194,
    latitude: 37.7749,
    zoom: 15,
    pitch: 60,
    bearing: -20
  });

  const safeJson = async (res, label) => {
    const contentType = res.headers.get('content-type') || '';
    if (!res.ok || !contentType.includes('application/json')) {
      const bodyPreview = (await res.text()).slice(0, 120);
      throw new Error(`${label} returned non-JSON body. Body preview: ${bodyPreview}`);
    }
    return res.json();
  };

  // 1. Initial REST Fetch
  useEffect(() => {
    fetch('http://localhost:8080/api/fleet/vehicles')
      .then(res => safeJson(res, 'GET /api/fleet/vehicles'))
      .then(data => {
        setVehicles(data);
        const found = data.find(v => v.id === id);
        if (found) setVehicle(found);
      })
      .catch(err => console.error("Vehicle fetch failed:", err));

    fetch(`http://localhost:8080/api/fleet/vehicles/${id}/history`)
      .then(res => safeJson(res, `GET /api/fleet/vehicles/${id}/history`))
      .then(data => {
        if (data && data.length > 0) {
          setHistory(data);
          setCurrentIndex(data.length - 1);

          const last = data[data.length - 1];
          if (last.longitude && last.latitude) {
            setViewState(prev => ({
              ...prev,
              longitude: Number(last.longitude),
              latitude: Number(last.latitude)
            }));
          }
        }
      })
      .catch(err => console.error("History fetch failed:", err));
  }, [id]);

  // 2. WebSocket Telemetry Stream
  useEffect(() => {
    const socket = new SockJS('http://localhost:8080/ws-telemetry');
    const stompClient = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        stompClient.subscribe(`/topic/telemetry.${id}.position`, message => {
          let payload;
          try {
            payload = JSON.parse(message.body);
          } catch (err) {
            return;
          }
          if (!payload.timestamp) payload.timestamp = new Date().toISOString();

          setHistory(prev => [...prev, payload]);
        });
      }
    });

    stompClient.activate();
    return () => stompClient.deactivate();
  }, [id]);

  // 3. Live Mode Index Tracker
  useEffect(() => {
    if (isLive && history.length > 0) {
      setCurrentIndex(history.length - 1);
    }
  }, [history.length, isLive]);

  // 4. Playback Scrubber Timer
  useEffect(() => {
    if (!isPlaying || isLive || history.length === 0) return;
    const interval = setInterval(() => {
      setCurrentIndex(prev => {
        if (prev >= history.length - 1) {
          setIsPlaying(false);
          return prev;
        }
        return prev + 1;
      });
    }, 100);
    return () => clearInterval(interval);
  }, [isPlaying, isLive, history.length]);

  const activePoint = history[currentIndex];

  // Camera Auto-Follow
  useEffect(() => {
    if (activePoint && autoFollow) {
      setViewState(prev => ({
        ...prev,
        longitude: Number(activePoint.longitude),
        latitude: Number(activePoint.latitude),
        transitionDuration: isPlaying ? 100 : 400
      }));
    }
  }, [activePoint, isPlaying, autoFollow]);

  const telemetry = useMemo(() => {
    if (!activePoint) return null;
    return { ...activePoint, ...(activePoint.metrics || {}) };
  }, [activePoint]);

  const isDark = theme === 'dark';
  const rawColor = getVehicleColor(id);
  const isValidHex = typeof rawColor === 'string' && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(rawColor);
  const webGLColor = isValidHex ? rawColor : '#FF3366';

  const mapStyle = useMemo(() => ({
    version: 8,
    sources: {
      osm: {
        type: 'raster',
        tiles: ['https://a.tile.openstreetmap.org/{z}/{x}/{y}.png'],
        tileSize: 256
      }
    },
    layers: [{ id: 'osm', type: 'raster', source: 'osm', minzoom: 0, maxzoom: 19 }]
  }), []);

  const hudBg = isDark ? 'var(--bg-glass, rgba(18, 18, 22, 0.95))' : 'rgba(255, 255, 255, 0.95)';
  const textColor = isDark ? '#fff' : '#111';
  const subtextColor = isDark ? '#888' : '#555';
  const borderColor = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.1)';
  const btnBg = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.04)';

  const controlColors = {
    flat2D: '#00b4d8',
    view3D: '#7209b7',
    north: '#f72585',
    east: '#4cc9f0',
    south: '#4895ef',
    west: '#3a0ca3',
    focus: '#10b981'
  };

  const getColoredBtnStyle = (isActive, activeColor) => ({
    flex: 1,
    background: isActive ? activeColor : btnBg,
    border: `1px solid ${isActive ? activeColor : borderColor}`,
    borderRadius: '6px',
    color: isActive ? '#fff' : subtextColor,
    fontSize: '11px',
    padding: '6px 0',
    cursor: 'pointer',
    textTransform: 'uppercase',
    fontWeight: '700',
    transition: 'all 0.2s ease',
    boxShadow: isActive ? `0 4px 12px ${activeColor}50` : 'none'
  });

  const isAngleActive = (current, target) => Math.abs(current - target) < 2;

  const pathCoordinates = useMemo(() => {
    if (history.length < 2 || currentIndex < 1) return null;
    const validCoords = [];
    let lastPoint = null;

    for (let i = 0; i <= currentIndex; i++) {
      const p = history[i];
      if (p && p.longitude != null && p.latitude != null) {
        let lon = Number(p.longitude);
        let lat = Number(p.latitude);
        if (Math.abs(lat) > 90 && Math.abs(lon) <= 90) {
          const temp = lat; lat = lon; lon = temp;
        }
        if (!isNaN(lon) && !isNaN(lat) && Math.abs(lat) <= 90 && Math.abs(lon) <= 180) {
          if (!lastPoint || lastPoint[0] !== lon || lastPoint[1] !== lat) {
            validCoords.push([lon, lat]);
            lastPoint = [lon, lat];
          }
        }
      }
    }
    return validCoords.length >= 2 ? validCoords : null;
  }, [history, currentIndex]);

  const fitPathToBounds = () => {
    if (!pathCoordinates || pathCoordinates.length < 2 || !mapRef.current) return;
    let minLng = Infinity, maxLng = -Infinity, minLat = Infinity, maxLat = -Infinity;
    for (const [lng, lat] of pathCoordinates) {
      if (lng < minLng) minLng = lng;
      if (lng > maxLng) maxLng = lng;
      if (lat < minLat) minLat = lat;
      if (lat > maxLat) maxLat = lat;
    }

    const map = mapRef.current.getMap ? mapRef.current.getMap() : mapRef.current;
    map.fitBounds(
      [[minLng, minLat], [maxLng, maxLat]],
      { padding: 80, duration: 800, maxZoom: 18 }
    );
    setIsFocused(true);
  };

  const formatTimestamp = (ts) => {
    if (!ts) return 'No Data';
    const date = new Date(ts);
    if (isNaN(date.getTime())) return String(ts);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  };

  const filteredVehicles = vehicles.filter(v =>
    v.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    v.id.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const isGround = vehicle?.category === 'GROUND';
  const displayAlt = isGround ? 0 : (activePoint?.altitude || 50);
  const hiddenKeys = ['id', 'vehicleId', 'vehicle_id', 'timestamp', 'metrics', 'additionalProperties', 'latitude', 'longitude', 'altitude', 'battery_level'];

  return (
    <div style={{ width: '100vw', height: '100vh', display: 'flex', flexDirection: 'column', background: isDark ? '#111' : '#eee' }}>

      {/* HEADER */}
      <div style={{ padding: '16px 24px', background: isDark ? '#1a1a20' : '#fff', borderBottom: `1px solid ${isDark ? '#333' : '#ddd'}`, display: 'flex', justifyContent: 'space-between', alignItems: 'center', zIndex: 10 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          {/* BACK TO FLEET BUTTON WITH HOVER EFFECT */}
          <button
            onClick={() => navigate('/ManageFleetPage.js')}
            onMouseEnter={() => setIsBackHovered(true)}
            onMouseLeave={() => setIsBackHovered(false)}
            style={{
              background: isBackHovered ? (isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.05)') : 'transparent',
              border: 'none',
              color: isBackHovered ? webGLColor : (isDark ? '#fff' : '#000'),
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              fontSize: '14px',
              fontWeight: '500',
              padding: '6px 10px',
              borderRadius: '8px',
              transition: 'all 0.2s ease'
            }}
          >
            <ArrowLeft size={16} /> Back to Fleet
          </button>

          <div style={{ width: '1px', height: '24px', background: isDark ? '#333' : '#ddd' }} />

          {/* SEARCH BAR & VEHICLE SELECTOR DROPDOWN */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
              <Search size={14} color={subtextColor} style={{ position: 'absolute', left: '10px' }} />
              <input
                type="text"
                placeholder="Search vehicle..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                style={{
                  background: isDark ? '#22222c' : '#ffffff',
                  color: textColor,
                  border: `1px solid ${borderColor}`,
                  borderRadius: '8px',
                  padding: '8px 10px 8px 32px',
                  fontSize: '13px',
                  outline: 'none',
                  width: '140px'
                }}
              />
            </div>

            <select
              value={id}
              onChange={(e) => navigate(`/vehicle/${e.target.value}`)}
              style={{
                background: isDark ? '#22222c' : '#ffffff',
                color: textColor,
                border: `1px solid ${borderColor}`,
                borderRadius: '8px',
                padding: '8px 14px',
                fontSize: '14px',
                fontWeight: '600',
                cursor: 'pointer',
                outline: 'none',
                boxShadow: 'none'
              }}
            >
              {filteredVehicles.length > 0 ? (
                filteredVehicles.map(v => (
                  <option key={v.id} value={v.id} style={{ background: isDark ? '#1a1a20' : '#ffffff', color: textColor }}>
                    {v.name} ({v.category})
                  </option>
                ))
              ) : (
                <option disabled value="">No vehicles found</option>
              )}
            </select>
          </div>

          <span style={{ fontSize: '12px', padding: '4px 8px', borderRadius: '12px', background: `${webGLColor}20`, color: webGLColor, fontWeight: '600' }}>
            Historical DVR & Live Feed
          </span>
        </div>
      </div>

      {/* MAP AREA */}
      <div style={{ flex: 1, position: 'relative' }}>
        <Map
          ref={mapRef}
          {...viewState}
          onMove={evt => setViewState(evt.viewState)}
          onDragStart={() => setIsFocused(false)}
          onZoomStart={() => setIsFocused(false)}
          mapStyle={mapStyle}
          style={{ width: '100%', height: '100%' }}
        >
          <NavigationControl position="bottom-right" visualizePitch={true} />

          {activePoint && (
            <Marker longitude={Number(activePoint.longitude)} latitude={Number(activePoint.latitude)} anchor="bottom">
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <div style={{ background: webGLColor, color: '#000', borderRadius: '8px', padding: '6px', boxShadow: `0 0 15px ${webGLColor}`, transform: `translateY(-${displayAlt}px)` }}>
                  {isGround ? <Truck size={16} /> : <Plane size={16} />}
                </div>
                <div style={{ width: '2px', height: `${displayAlt}px`, background: `linear-gradient(to bottom, ${webGLColor}, transparent)` }} />
                <div style={{ width: '12px', height: '4px', background: 'rgba(0,0,0,0.6)', borderRadius: '50%', boxShadow: '0 0 4px rgba(0,0,0,0.8)' }} />
              </div>
            </Marker>
          )}
        </Map>

        {/* TELEMETRY PANEL */}
        {telemetry && (
          <div style={{
            position: 'absolute', top: '20px', left: '20px', background: hudBg, backdropFilter: 'blur(15px)',
            border: `1px solid ${borderColor}`, borderRadius: '16px', padding: '20px', color: textColor,
            zIndex: 10, width: '280px', boxShadow: '0 20px 40px rgba(0,0,0,0.15)', maxHeight: 'calc(100vh - 160px)', overflowY: 'auto'
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '16px' }}>
              <Gauge size={18} color={webGLColor} />
              <h3 style={{ margin: 0, fontSize: '14px', textTransform: 'uppercase', letterSpacing: '1px' }}>Live Telemetry</h3>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
              <div><div style={{ fontSize: '11px', color: subtextColor, textTransform: 'uppercase' }}>Latitude</div><div style={{ fontSize: '14px', fontWeight: '600' }}>{Number(telemetry.latitude).toFixed(5)}</div></div>
              <div><div style={{ fontSize: '11px', color: subtextColor, textTransform: 'uppercase' }}>Longitude</div><div style={{ fontSize: '14px', fontWeight: '600' }}>{Number(telemetry.longitude).toFixed(5)}</div></div>

              {!isGround && (
                <div><div style={{ fontSize: '11px', color: subtextColor, textTransform: 'uppercase' }}>Altitude</div><div style={{ fontSize: '14px', fontWeight: '600' }}>{Number(telemetry.altitude || 0).toFixed(1)}m</div></div>
              )}
              {telemetry.battery_level !== undefined && (
                <div><div style={{ fontSize: '11px', color: subtextColor, textTransform: 'uppercase' }}>Battery</div><div style={{ fontSize: '14px', fontWeight: '600', color: telemetry.battery_level < 20 ? '#ff3b30' : textColor }}>{telemetry.battery_level}%</div></div>
              )}

              {Object.keys(telemetry)
                .filter(key => !hiddenKeys.includes(key))
                .map(key => (
                  <div key={key}>
                    <div style={{ fontSize: '11px', color: subtextColor, textTransform: 'uppercase' }}>{key.replace(/_/g, ' ')}</div>
                    <div style={{ fontSize: '14px', fontWeight: '600' }}>{telemetry[key]}</div>
                  </div>
                ))}
            </div>
          </div>
        )}

        {/* HUD CAMERA CONTROLS */}
        {isHudExpanded ? (
          <div style={{
            position: 'absolute', top: '20px', right: '20px', background: hudBg, backdropFilter: 'blur(15px)',
            border: `1px solid ${borderColor}`, borderRadius: '16px', padding: '20px', color: textColor,
            boxShadow: '0 20px 40px rgba(0,0,0,0.15)', zIndex: 10, display: 'flex', flexDirection: 'column', gap: '20px', width: '270px'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span style={{ fontSize: '13px', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Camera Settings</span>
              <X size={18} color={subtextColor} style={{ cursor: 'pointer' }} onClick={() => setIsHudExpanded(false)} />
            </div>

            {/* FOCUS PATH BUTTON */}
            <button
              onClick={fitPathToBounds}
              style={{
                width: '100%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px',
                fontSize: '12px',
                padding: '8px 12px',
                borderRadius: '8px',
                border: `1px solid ${isFocused ? controlColors.focus : borderColor}`,
                background: isFocused ? `${controlColors.focus}25` : btnBg,
                color: isFocused ? controlColors.focus : textColor,
                cursor: 'pointer',
                fontWeight: '700',
                transition: 'all 0.2s'
              }}
            >
              <Maximize2 size={14} /> Focus Path {isFocused && '✓'}
            </button>

            {/* PITCH ANGLE WITH 3D ICON */}
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '10px' }}>
                <div style={{ width: '38px', height: '38px', borderRadius: '10px', background: btnBg, border: `1px solid ${borderColor}`, display: 'flex', justifyContent: 'center', alignItems: 'center', perspective: '100px' }}>
                  <Layers size={20} color={controlColors.view3D} style={{ transform: `rotateX(${viewState.pitch}deg)`, transformStyle: 'preserve-3d', transition: 'transform 0.2s ease' }}/>
                </div>
                <div>
                  <div style={{ fontSize: '10px', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Pitch Angle</div>
                  <div style={{ fontSize: '15px', fontWeight: '600' }}>{Math.round(viewState.pitch)}°</div>
                </div>
              </div>
              <input type="range" min="0" max="85" value={viewState.pitch} onChange={e => setViewState(prev => ({ ...prev, pitch: Number(e.target.value) }))} style={{ width: '100%', cursor: 'pointer', accentColor: controlColors.view3D, marginBottom: '8px' }} />
              <div style={{ display: 'flex', gap: '8px' }}>
                <button style={getColoredBtnStyle(isAngleActive(viewState.pitch, 0), controlColors.flat2D)} onClick={() => setViewState(prev => ({ ...prev, pitch: 0 }))}>2D Flat</button>
                <button style={getColoredBtnStyle(isAngleActive(viewState.pitch, 65), controlColors.view3D)} onClick={() => setViewState(prev => ({ ...prev, pitch: 65 }))}>3D View</button>
              </div>
            </div>

            <div style={{ height: '1px', background: borderColor }} />

            {/* COMPASS ROSE BEARING UI */}
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '10px' }}>
                <div style={{ width: '38px', height: '38px', borderRadius: '50%', background: btnBg, border: `1px solid ${borderColor}`, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                  <Compass size={20} color={controlColors.north} style={{ transform: `rotate(${viewState.bearing - 45}deg)`, transition: 'transform 0.3s ease' }}/>
                </div>
                <div>
                  <div style={{ fontSize: '10px', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Bearing</div>
                  <div style={{ fontSize: '15px', fontWeight: '600' }}>{Math.round(viewState.bearing)}°</div>
                </div>
              </div>

              <input type="range" min="-180" max="180" value={viewState.bearing} onChange={e => setViewState(prev => ({ ...prev, bearing: Number(e.target.value) }))} style={{ width: '100%', cursor: 'pointer', accentColor: controlColors.north, marginBottom: '12px' }} />

              {/* COMPASS GRID */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '6px', maxWidth: '180px', margin: '0 auto' }}>
                <div />
                <button style={getColoredBtnStyle(isAngleActive(viewState.bearing, 0), controlColors.north)} onClick={() => setViewState(prev => ({ ...prev, bearing: 0 }))}>N</button>
                <div />

                <button style={getColoredBtnStyle(isAngleActive(viewState.bearing, -90), controlColors.west)} onClick={() => setViewState(prev => ({ ...prev, bearing: -90 }))}>W</button>
                <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}><Navigation size={14} color={subtextColor} style={{ transform: `rotate(${viewState.bearing - 45}deg)`, transition: 'transform 0.3s ease' }} /></div>
                <button style={getColoredBtnStyle(isAngleActive(viewState.bearing, 90), controlColors.east)} onClick={() => setViewState(prev => ({ ...prev, bearing: 90 }))}>E</button>

                <div />
                <button style={getColoredBtnStyle(isAngleActive(viewState.bearing, 180) || isAngleActive(viewState.bearing, -180), controlColors.south)} onClick={() => setViewState(prev => ({ ...prev, bearing: 180 }))}>S</button>
                <div />
              </div>
            </div>
          </div>
        ) : (
          <div onClick={() => setIsHudExpanded(true)} style={{ position: 'absolute', top: '20px', right: '20px', background: hudBg, border: `1px solid ${borderColor}`, borderRadius: '50%', width: '44px', height: '44px', display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', zIndex: 10, color: textColor, transition: 'all 0.2s ease' }}>
            <Camera size={20} />
          </div>
        )}
      </div>

      {/* BOTTOM TIMELINE CONTROLS */}
      <div style={{ padding: '24px', background: isDark ? '#1a1a20' : '#fff', borderTop: `1px solid ${isDark ? '#333' : '#ddd'}`, zIndex: 10 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '24px', maxWidth: '1200px', margin: '0 auto' }}>

          <button onClick={() => { setIsPlaying(!isPlaying); setIsLive(false); }} style={{ width: '48px', height: '48px', borderRadius: '50%', border: 'none', background: isLive ? '#333' : webGLColor, color: '#000', display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', boxShadow: isPlaying ? `0 0 15px ${webGLColor}` : 'none', transition: 'all 0.2s' }}>
            {isPlaying ? <Pause size={20} fill="currentColor"/> : <Play size={20} fill="currentColor" style={{ marginLeft: '4px' }}/>}
          </button>

          <button onClick={() => setAutoFollow(!autoFollow)} title="Toggle Camera Auto-Follow" style={{ width: '42px', height: '42px', borderRadius: '10px', border: `1px solid ${autoFollow ? webGLColor : borderColor}`, background: autoFollow ? webGLColor : btnBg, color: autoFollow ? '#fff' : subtextColor, display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', transition: 'all 0.2s', boxShadow: autoFollow ? `0 4px 12px ${webGLColor}50` : 'none' }}>
            <Crosshair size={20} />
          </button>

          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', color: isDark ? '#aaa' : '#555', fontSize: '13px' }}>
              <span style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                <Clock size={14} />
                {formatTimestamp(activePoint?.timestamp)}
              </span>
              <span>Point: {history.length > 0 ? currentIndex + 1 : 0} / {history.length}</span>
            </div>

            <input
              type="range"
              min="0"
              max={Math.max(0, history.length - 1)}
              value={currentIndex}
              onChange={(e) => {
                setCurrentIndex(Number(e.target.value));
                setIsLive(false);
                setIsPlaying(false);
              }}
              style={{ width: '100%', cursor: 'pointer', accentColor: webGLColor }}
              disabled={history.length === 0}
            />
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px', minWidth: '100px' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', color: isDark ? '#fff' : '#000', fontSize: '14px', fontWeight: '600' }}>
              <input
                type="checkbox"
                checked={isLive}
                onChange={(e) => {
                  const active = e.target.checked;
                  setIsLive(active);
                  if (active) {
                    setIsPlaying(false);
                    if (history.length > 0) {
                      setCurrentIndex(history.length - 1);
                    }
                  }
                }}
                style={{ width: '18px', height: '18px', accentColor: '#ff3b30' }}
              />
              <Activity size={16} color={isLive ? "#ff3b30" : (isDark ? '#888' : '#555')} /> LIVE
            </label>
          </div>

        </div>
      </div>
    </div>
  );
}
